const express = require('express');
const { apiKeyAuth } = require('../middleware/apiKey');
const { WebhookEndpoint, WebhookDelivery } = require('../models/webhook');

const app = express();

app.get('/api/webhooks/:webhookId/deliveries', apiKeyAuth, async (req, res) => {
  const { webhookId } = req.params;
  const authenticatedOrgId = req.apiKey.organizationId;

  // Verify the webhook endpoint belongs to the API key's organization
  const endpoint = await WebhookEndpoint.findOne({
    where: { id: webhookId, organizationId: authenticatedOrgId }
  });

  if (!endpoint) {
    return res.status(404).json({ error: 'Webhook endpoint not found or access denied' });
  }

  const deliveries = await WebhookDelivery.findAll({
    where: {
      webhookId,
      organizationId: authenticatedOrgId
    }
  });

  res.json({ webhookId, deliveries });
});

module.exports = app;
